insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Aggression', 'brand', 'board_brand', 1983, 'USA', NULL, NULL, 'verified', NULL, 'Origins as Boulder Boards; factory formerly Naked Boards. Bought by Volant 1994; ended 1999. | TWS Oct 1992 guide: ''for seven years, Aggression Snowboards has been producing boards ... from their factory in Boulder, Colorado'' (implies c.1985-86 start; Michigan museum lists ''Agression 1983''). Purchased by Volant Skis in 1994.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Airwalk', 'brand', 'board_brand', 1986, 'USA', NULL, NULL, 'unverified', NULL, 'Shoe company; led snowboard boot sales by 1994 and also made snowboards, bindings and accessories. | Shoe brand; step-in bindings 1995 (timeline); A-1 board in the 2000 Snowboard Life Top 25.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Amplid', 'brand', 'board_brand', 2004, 'Germany', NULL, NULL, 'verified', NULL, 'Brand page gives 2004 founding, co-founded with Anian Thrainer in 2005; Thrainer left 2014, Conrad Albert joined. Amplid GmbH. | Amplid GmbH; co-owned with Anian Thrainer early on; Peter Bauer later 100% owner.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Atomic', 'brand', 'board_brand', NULL, 'Austria', NULL, NULL, 'verified', NULL, 'Ski maker; snowboard line (Alibi etc.) and owner of the Oxygen snowboard brand in the 1990s. | Ski manufacturer; snowboards seen in SnowDB 2009/10-2011/12 only. Status of snowboard line not confirmed.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Avalanche', 'brand', 'board_brand', 1982, 'USA', NULL, NULL, 'verified', NULL, 'First boards Huey, Dewey & Louie with Formica; Damian Sanders pro models. 80% sold to Bob Edwards in 1994; merged with Straight Line into A Sport Dec 1997; brand effectively ended 1997. | ISM 1988 address P.O. Box 10636, South Lake Tahoe. Snowboarder timeline dates the first Avalanche boards (Huey, Dewey, Louie) to 1982. Still listed in 2000-01 Snowboard Life test.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'BC Stream', 'brand', 'board_brand', NULL, 'Japan', NULL, NULL, 'unverified', NULL, 'Japanese carving/freeride brand (Hammerhead models). | Only homepage reachable; model names not extracted. THIN.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Cardiff', 'brand', 'board_brand', NULL, 'USA', NULL, NULL, 'unverified', NULL, 'Cardiff Snowcraft. Earliest model year sourced 2020 (Crane).');
