insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Division 23', 'brand', 'board_brand', 1993, 'Canada', NULL, NULL, 'unverified', NULL, 'Canadian 1990s brand; Peter Line''s rainbow pro model before Forum. Acquired by Jaysport with Type A and Atlantis in 1999. | TWS Oct 1993 describes L.A.-based Division 23 as a new company spearheaded by ex-Barfoot/Kemper worker Greg DiLeo with a new-school focus.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Donek', 'brand', 'board_brand', 1987, 'USA', NULL, NULL, 'verified', NULL, 'Started as a high-school project; incorporated 1995; Watkins facility 1999. Custom carving/race/freeride boards. | Custom softboot and alpine hardboot boards.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Dupraz', 'brand', 'board_brand', 2004, 'France', NULL, NULL, 'verified', NULL, 'D1 all-mountain shape; c.2003/04 (Whitelines A-Z says 2003). | Minimal line: D1 in several lengths plus D-Tour split.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'F2', 'brand', 'board_brand', 1979, 'Germany', NULL, NULL, 'verified', NULL, '''Fun & Function'' windsurf company (1979); became a leading race/hardboot snowboard maker (Silberpfeil, Speedster); freestyle division FTWO. Ownership: Brockhaus -> KJ Jacobs/Boards & More 2000 -> F2 International GmbH 2007 -> Bernd Flugel 2009 -> F2 Fun & Function GmbH 2015. Museum lists first snowboards 1988 Austrian-made. | Michigan Snowboard Museum reference list: ''F2 (Fun & Function) 1988, Austrian made''. No model rows captured.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Fanatic', 'brand', 'board_brand', 1981, 'Germany', NULL, NULL, 'unverified', NULL, 'Windsurf brand with a snowboard line (Michigan museum dates snowboards 1989); sold to Mistral group end 1999 including snowboard brands. Snowboards no longer made. | Windsurf brand; snowboards in TWS Oct 1989 guide (Ultra series).');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Flite', 'brand', 'board_brand', NULL, 'USA', NULL, NULL, 'verified', NULL, 'Derrah started with skateboards 1974 and prototyped snurfer-style decks by 1975; snowboards early 1980s (VTSSM says 1982). Introduced Hy-Bak binding (Jeff Grell). Ceased 1992. Founding year of the snowboard brand not firmly documented. | ISM 1988 address 58 Kingston Avenue, Newport, RI. Snowboarder timeline notes Flite boards with highback bindings in 1983.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Flow', 'brand', 'board_brand', 1996, 'USA', NULL, NULL, 'verified', NULL, 'Speed-entry binding pioneer that expanded to boards and boots; merged with Nidecker bindings 2024. | Best known for rear-entry bindings (Whitelines); board line 2008-2012 in SnowDB. Parent company not confirmed from sources consulted.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Head', 'brand', 'board_brand', NULL, 'Austria', NULL, NULL, 'verified', NULL, 'Ski/tennis group; snowboard line grew from the fusion of small brand Blax with Head. Whitelines A-Z dates the snowboard entry to 2000. | Whitelines: Head snowboard division started 2000/2001 (Klaus Thurner, Charly Messmer). 2008-2012 boards in SnowDB.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Hooger Booger', 'brand', 'board_brand', 1983, 'Switzerland', NULL, NULL, 'verified', NULL, 'Pioneered asymmetric sidecuts; neon pink ''feather'' branding. Bought by Scott Corporation and later discontinued. | ISM 1988: ''Sporting Goods by Kitchener'', Bern. TWS Oct 1992: making boards for ten years, claims first modern asymmetrical boards (Snowboarder timeline: asym board 1986).');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'HOT', 'brand', 'board_brand', 1984, 'Switzerland', NULL, NULL, 'verified', NULL, 'Founded winter 1983/84; Revolution (1988) and One Sixty enabled extreme carving. Dupraz licensed production 1990 and left 1991; brand disappeared, later owned by Grand Chavin (with Hammer) which merged with A Snowboards in 1997. Relaunched by Dupraz in 2019. | Michigan museum reference list dates Hot to 1984; Revolution model 1988.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Joyride', 'brand', 'board_brand', NULL, 'Canada', NULL, NULL, 'unverified', NULL, 'Mid-1990s street/skate-inspired brand (Plan B / Danny Way collaboration); now reissuing original boards. | Early-1990s brand; five boards (1992-1993) catalogued at Retro Snow museum. No other facts confirmed. | TWS Oct 1993: Solid facility run by Joyride founder Andy Shotts in Fairplay, CO; Ken Greenguard president.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Lamar', 'brand', 'board_brand', 1989, 'USA', NULL, NULL, 'verified', NULL, 'Bert LaMar (1987 World Halfpipe Champion; earlier Look Lamar boards) started Lamar from a garage in 1989; sold to Gen-X 1998. Continued as a price-point brand into the 2010s (Snowboarder 2011 preview, SnowDB). | Appears as its own brand (''LaMar'') in TWS guides from the Oct 1991 issue after the Look Lamar era.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Lobster', 'brand', 'board_brand', 2011, 'Iceland', NULL, NULL, 'verified', NULL, 'Twin freestyle boards with Bataleon 3BT; phased out by Nidecker in 2025. | Uses Bataleon Triple Base Technology; made with Low Pressure Studio.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Look', 'brand', 'board_brand', 1986, 'France', NULL, NULL, 'verified', NULL, 'French binding maker''s snowboard line; Bert Lamar Freestyle ''Trick Stick'' (1988) claimed as first twin-tip freestyle board. Faded by 1994. | Ski-binding maker whose snowboard line (1988-1991 in sources) carried the Bert Lamar pro models before Lamar became its own brand.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Mistral', 'brand', 'board_brand', NULL, 'Netherlands', NULL, NULL, 'unverified', NULL, 'Windsurf company entered snowboards 1987 (Swallowtail model, tri-groove base). Michigan museum lists a Mistral in Maryland. Mistral group bought Fanatic (incl. snowboard brands) in 1999. | Windsurf brand with snowboards from 1987 (swallowtail) through the early 1990s.');
insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Moss Snowstick', 'brand', 'board_brand', 1971, 'Japan', NULL, NULL, 'verified', NULL, 'Japanese snowsurf pioneer; brand dates itself to 1971. First Moss snowsurf line 1979; Snowstick V-1 1981. Michigan museum credits ''Shinzo Kamakura'' (Kamakura is the Shonan location). | Japanese snowsurf pioneer; site states established 1971.');
