insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Option', 'brand', 'board_brand', 1992, 'Canada', NULL, NULL, 'verified', NULL, 'Formed 1991/Aug 1992 from Powder Stick; Canadian Exporter of the Year 1997; acquired NFA apparel. Vancouver factory later home to Wired. | Pique Newsmagazine: independent Vancouver manufacturer, CEO Geoff Power, 86 employees and 1997 sales over $6M; Kevin Sansalone and Chris Dufficy pro models. Last catalog seen is 2008/09 (SnowDB, Shayboarder). Closure year not confirmed.');
