insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Rad Air', 'brand', 'board_brand', 1991, 'Switzerland', NULL, NULL, 'verified', NULL, 'Tanker model; Volkl bought 49% in 1997; family-run (Fabian Gunz). | Rad-Air; famous for the Tanker longboard.');
