insert into orgs (id, name, org_type, brand_category, founded_year, country, website, wikidata_qid, community_status, added_by, description) values (gen_random_uuid(), 'Yonex', 'brand', 'board_brand', NULL, 'Japan', NULL, NULL, 'verified', NULL, 'Entered snowboards 1995 with the first carbon-infused snowboard; carbon cores. | Carbon snowboards; only 2026-27 lineup sourced. THIN.');
